// Re-pin the trusted hosted workflow bytes from two commits (offline, read-only git object access):
//   node work/actions-hosted-migration/independent-ci-v1/test/fixtures/repin-trusted-workflows.mjs --repo . --main <rev> --pr-b <rev>
// It rewrites the rows between the BEGIN/END markers of worker/trusted-workflows.mjs (the one table every formal
// role, role policy and signed-result check derives its accepted set from) and test/fixtures/trusted-workflows.json
// (the exact bytes the tests build trusted Sources from). `--check` writes nothing and exits 1 when either differs.
// Development tool only: no runtime module imports it.
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { TRUSTED_WORKFLOW_PATHS } from '../../worker/trusted-workflows.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
export const TABLE_FILE = path.join(HERE, '../../worker/trusted-workflows.mjs');
export const FIXTURE_FILE = path.join(HERE, 'trusted-workflows.json');
const BEGIN = '// BEGIN TRUSTED WORKFLOW ROWS (generated by test/fixtures/repin-trusted-workflows.mjs)\n', END = '// END TRUSTED WORKFLOW ROWS\n';
const SUCCESSOR_BEGIN = '// BEGIN GITLEAKS SUCCESSOR (generated from a real workflow-freeze commit)\n', SUCCESSOR_END = '// END GITLEAKS SUCCESSOR\n';
const TRIVY_BEGIN = '// BEGIN TRIVY SUCCESSOR (generated from a real workflow-freeze commit)\n', TRIVY_END = '// END TRIVY SUCCESSOR\n';
const fail = message => { throw Object.assign(new Error(message), { code: 'REPIN_REFUSED' }); };

function git(repo, args) {
  const r = spawnSync('git', ['-C', repo, ...args], { maxBuffer: 64 * 1024 * 1024, windowsHide: true,
    env: { ...process.env, GIT_CONFIG_NOSYSTEM: '1', GIT_OPTIONAL_LOCKS: '0', GIT_TERMINAL_PROMPT: '0' } });
  if (r.status !== 0) fail(`git ${args[0]} failed: ${String(r.stderr).slice(0, 200)}`);
  return r.stdout;
}

// { versions: { main: { commit, files: { path: { blob, sha256, lines } } }, 'pr-b': ... } } from the two commits.
// `lines` is the text split on \n (joined back with \n it is the exact bytes): one fixture line per workflow line,
// never one long line holding a whole workflow.
export function readVersions(repo, revs) {
  const versions = {};
  for (const [version, rev] of Object.entries(revs)) {
    if (typeof rev !== 'string' || !/^[A-Za-z0-9_./^~-]{1,200}$/.test(rev) || rev.startsWith('-')) fail(`invalid revision for ${version}`);
    const commit = git(repo, ['rev-parse', '--verify', '--end-of-options', `${rev}^{commit}`]).toString('utf8').trim();
    const files = {};
    for (const file of Object.values(TRUSTED_WORKFLOW_PATHS).sort()) {
      const blob = git(repo, ['rev-parse', '--verify', '--end-of-options', `${commit}:${file}`]).toString('utf8').trim();
      const bytes = git(repo, ['cat-file', 'blob', blob]);
      if (createHash('sha1').update(`blob ${bytes.length}\0`).update(bytes).digest('hex') !== blob) fail(`blob mismatch ${file}`);
      const text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
      files[file] = { blob, sha256: createHash('sha256').update(bytes).digest('hex'), lines: text.split('\n') };
    }
    versions[version] = { commit, files };
  }
  if (Object.values(TRUSTED_WORKFLOW_PATHS).some(file => versions.main.files[file].sha256 === versions['pr-b'].files[file].sha256))
    fail('a workflow has the same bytes on both sides; nothing to re-pin for it');
  return versions;
}

function readWorkflowSuccessor(repo, rev, file) {
  if (typeof rev !== 'string' || !/^[A-Za-z0-9_./^~-]{1,200}$/.test(rev) || rev.startsWith('-')) fail('invalid gitleaks successor revision');
  const commit = git(repo, ['rev-parse', '--verify', '--end-of-options', `${rev}^{commit}`]).toString('utf8').trim();
  const blob = git(repo, ['rev-parse', '--verify', '--end-of-options', `${commit}:${file}`]).toString('utf8').trim();
  const bytes = git(repo, ['cat-file', 'blob', blob]);
  if (createHash('sha1').update(`blob ${bytes.length}\0`).update(bytes).digest('hex') !== blob) fail('gitleaks successor blob mismatch');
  const text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  return { commit, files: { [file]: { blob, sha256: createHash('sha256').update(bytes).digest('hex'), lines: text.split('\n') } } };
}
export const readGitleaksSuccessor = (repo, rev) => readWorkflowSuccessor(repo, rev, TRUSTED_WORKFLOW_PATHS.gitleaks);
export const readTrivySuccessor = (repo, rev) => readWorkflowSuccessor(repo, rev, TRUSTED_WORKFLOW_PATHS.trivy);
export function fixtureText(versions, successors = {}) {
  return `${JSON.stringify({
    _comment: 'FIXTURE ONLY. Generated by repin-trusted-workflows.mjs: the exact reviewed bytes of the three hosted workflows the local formal roles pin, on main and in the frozen PR-B commit, one string per line (joined with \\n they are the exact bytes). The tests build trusted Sources from these bytes, never from the working tree, so they hold on either side of PR-B.',
    contract: 'clued.independent-ci.test.trusted-workflows/2', versions,
    ...(Object.keys(successors).length ? { successors } : {}) }, null, 2)}\n`;
}

export function rowsBlock(versions) {
  const rows = [];
  for (const file of Object.values(TRUSTED_WORKFLOW_PATHS).sort())
    for (const version of ['main', 'pr-b']) {
      const entry = versions[version].files[file];
      rows.push(`  ['${file}', '${entry.sha256}', '${entry.blob}', '${version} ${versions[version].commit}'],\n`);
    }
  return `${BEGIN}const ROWS = [\n  // [path, sha256 of the bytes, git blob, source]\n${rows.join('')}];\n${END}`;
}

export function tableText(current, versions) {
  const start = current.indexOf(BEGIN), end = current.indexOf(END);
  if (start < 0 || end < start || current.indexOf(BEGIN, start + 1) >= 0) fail('table markers not found exactly once');
  return current.slice(0, start) + rowsBlock(versions) + current.slice(end + END.length);
}
function workflowSuccessorTableText(current, successor, file, begin, finish, name) {
  const start = current.indexOf(begin), end = current.indexOf(finish);
  if (start < 0 || end < start || current.indexOf(begin, start + 1) >= 0) fail('successor table markers not found exactly once');
  const entry = successor?.files?.[file];
  if (successor && (!/^[a-f0-9]{40}$/.test(successor.commit) || Object.keys(successor.files).join('|') !== file
    || !/^[a-f0-9]{40}$/.test(entry?.blob ?? '') || !/^[a-f0-9]{64}$/.test(entry?.sha256 ?? ''))) fail('successor identity invalid');
  const row = successor ? { path: file, sha256: entry.sha256, blob: entry.blob, commit: successor.commit } : null;
  return current.slice(0, start) + begin + `const ${name} = ${JSON.stringify(row)};\n` + finish + current.slice(end + finish.length);
}
export const successorTableText = (current, successor = null) => workflowSuccessorTableText(current, successor, TRUSTED_WORKFLOW_PATHS.gitleaks, SUCCESSOR_BEGIN, SUCCESSOR_END, 'GITLEAKS_SUCCESSOR_ROW');
export const trivySuccessorTableText = (current, successor = null) => workflowSuccessorTableText(current, successor, TRUSTED_WORKFLOW_PATHS.trivy, TRIVY_BEGIN, TRIVY_END, 'TRIVY_SUCCESSOR_ROW');

export function main(argv = process.argv.slice(2)) {
  const options = {};
  for (let index = 0; index < argv.length; index++) {
    if (argv[index] === '--check') { options.check = true; continue; }
    if (!['--repo', '--main', '--pr-b', '--gitleaks-successor', '--trivy-successor'].includes(argv[index]) || argv[index + 1] === undefined) fail('usage: --repo <dir> --main <rev> --pr-b <rev> [--gitleaks-successor <rev>] [--trivy-successor <rev>] [--check]');
    options[argv[index]] = argv[++index];
  }
  if (!options['--repo'] || !options['--main'] || !options['--pr-b']) fail('usage: --repo <dir> --main <rev> --pr-b <rev> [--check]');
  const versions = readVersions(options['--repo'], { main: options['--main'], 'pr-b': options['--pr-b'] });
  const successors = fs.existsSync(FIXTURE_FILE) ? JSON.parse(fs.readFileSync(FIXTURE_FILE, 'utf8')).successors ?? {} : {};
  if (options['--gitleaks-successor']) successors.gitleaks729 = readGitleaksSuccessor(options['--repo'], options['--gitleaks-successor']);
  if (options['--trivy-successor']) successors.trivy = readTrivySuccessor(options['--repo'], options['--trivy-successor']);
  const table = trivySuccessorTableText(successorTableText(tableText(fs.readFileSync(TABLE_FILE, 'utf8'), versions), successors.gitleaks729 ?? null), successors.trivy ?? null), fixture = fixtureText(versions, successors);
  const same = table === fs.readFileSync(TABLE_FILE, 'utf8') && fs.existsSync(FIXTURE_FILE) && fixture === fs.readFileSync(FIXTURE_FILE, 'utf8');
  if (options.check) { console.log(JSON.stringify({ status: same ? 'TRUSTED_WORKFLOWS_CURRENT' : 'TRUSTED_WORKFLOWS_DIFFER' })); return same ? 0 : 1; }
  fs.writeFileSync(TABLE_FILE, table); fs.writeFileSync(FIXTURE_FILE, fixture);
  console.log(JSON.stringify({ status: same ? 'TRUSTED_WORKFLOWS_UNCHANGED' : 'TRUSTED_WORKFLOWS_REPINNED',
    main: versions.main.commit, prB: versions['pr-b'].commit }));
  return 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  try { process.exitCode = main(); } catch (error) { console.error(error.message); process.exitCode = 2; }
}
